// 3 정규화 + 시간창 + 실행내 중복제거
// Mode: Run Once for All Items

const WINDOW_HOURS = 24;   // A-01: 실행 시점 기준 직전 24시간.
                           // 브리핑에 실리는 기사는 '항상 최신'이어야 합니다.
                           // 창을 넓히면 어제/그제 기사가 오늘 브리핑에 섞이므로 넓히지 말 것.
                           // (v1.4에서 48h로 늘렸다가 v1.5에서 되돌림)
const SNIPPET_MAX  = 1200; // LLM 입력 토큰 절약

function sha256(str) {
  try {
    return crypto.createHash('sha256').update(str).digest('hex');
  } catch (e) {
    let h1 = 0xcbf29ce484222325n, h2 = 0x84222325cbf29ce4n;
    const P = 0x100000001b3n, M = 0xFFFFFFFFFFFFFFFFn;
    for (const ch of str) {
      const c = BigInt(ch.codePointAt(0));
      h1 = ((h1 ^ c) * P) & M;
      h2 = ((h2 ^ (c + 7n)) * P) & M;
    }
    return h1.toString(16).padStart(16, '0') + h2.toString(16).padStart(16, '0');
  }
}

const TRACKING_PREFIXES = ['utm_', 'fbclid', 'gclid', 'igshid', 'spm', '_ga'];
const TRACKING_EXACT = new Set(['ref','src','source','cid','mid','sid','from','inputkey','utm','nav']);

function normalizeUrl(raw) {
  if (!raw) return '';
  const s = String(raw).trim();
  try {
    const u = new URL(s);
    u.protocol = 'https:';
    u.hostname = u.hostname.toLowerCase().replace(/^www\./, '');
    u.hash = '';
    const keep = [];
    for (const [k, v] of u.searchParams.entries()) {
      const lk = k.toLowerCase();
      if (TRACKING_PREFIXES.some(p => lk.startsWith(p))) continue;
      if (TRACKING_EXACT.has(lk)) continue;
      keep.push([k, v]);
    }
    keep.sort((a, b) => a[0].localeCompare(b[0]));
    u.search = keep.length ? '?' + keep.map(([k, v]) => k + '=' + v).join('&') : '';
    return u.toString().replace(/\/+$/, '');
  } catch (e) {
    return s.toLowerCase().replace(/[#?].*$/, '').replace(/\/+$/, '');
  }
}

function sourceOf(j) {
  const link = String(j.link || j.guid || j.id || '');
  if (link.includes('yna.co.kr')) return '연합뉴스';
  if (link.includes('hankyung.com')) return '한국경제';
  if (link.includes('mk.co.kr')) return '매일경제';
  return '기타';
}

const now = new Date();
const windowStart = new Date(now.getTime() - WINDOW_HOURS * 3600 * 1000);
const runDate = new Intl.DateTimeFormat('sv-SE', { timeZone: 'Asia/Seoul' }).format(now);
const runId = String($execution.id);

const seen = new Set();
const out = [];
const counters = { raw: 0, out_of_window: 0, dup_in_run: 0, no_link: 0 };

for (const item of $input.all()) {
  const j = item.json || {};
  if (j._empty || (!j.link && !j.guid && !j.id && !j.title)) { continue; }
  counters.raw++;

  const rawLink = j.link || j.guid || j.id || '';
  if (!rawLink) { counters.no_link++; continue; }

  const normalized = normalizeUrl(rawLink);
  const hash = sha256(normalized);

  if (seen.has(hash)) { counters.dup_in_run++; continue; }
  seen.add(hash);

  const rawDate = j.isoDate || j.pubDate || j.pubdate || j.date || null;
  const d = rawDate ? new Date(rawDate) : null;
  const parsed = d instanceof Date && !isNaN(d.getTime());
  if (parsed && (d < windowStart || d > now)) { counters.out_of_window++; continue; }

  const snippetRaw = j.contentSnippet || j.content || j.description || j.summary || '';
  const snippet = String(snippetRaw)
    .replace(/<[^>]*>/g, ' ')
    .replace(/&[a-z]+;/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, SNIPPET_MAX);

  out.push({ json: {
    url_hash: hash,
    normalized_url: normalized,
    original_url: String(rawLink),
    title: String(j.title || '').replace(/\s+/g, ' ').trim(),
    source: sourceOf(j),
    published_at: parsed ? d.toISOString() : '',
    pub_parsed: parsed,
    snippet,
    run_id: runId,
    run_date: runDate,
    _counters: counters,
  }});
}

if (out.length === 0) {
  return [{ json: { _empty: true, run_id: runId, run_date: runDate, _counters: counters } }];
}
return out;

// 5 중복 대조 + 금융 키워드 필터  (둘 다 LLM 이전)
// Mode: Run Once for All Items

const HISTORY_DAYS = 7;   // D-03
const SCORE_MIN    = 2;

const BLOCK = ['연예','아이돌','드라마','예능','배우','가수','열애','결혼설','이혼',
  '프로야구','축구','야구','골프','올림픽','월드컵','리그','선수단','감독 선임',
  '날씨','미세먼지','폭염','한파','태풍 경로',
  '음주운전','살인','성폭행','마약 투약','운세','별자리','로또 당첨번호'];

const STRONG = ['기준금리','금통위','한국은행','연준','FOMC','파월',
  '코스피','코스닥','나스닥','S&P','다우','지수','증시','주가','상장','공모주','IPO',
  '환율','원달러','달러화','엔화','위안화','외환보유액',
  '국채','회사채','채권','금리','스프레드',
  '영업이익','순이익','실적','어닝','매출',
  '인수합병','M&A','지분 인수','유상증자','자사주',
  '물가','소비자물가','CPI','PPI','GDP','경상수지','무역수지',
  '부동산','아파트값','집값','전세','분양','청약','재건축',
  '금융위','금감원','기재부','세제 개편','규제 완화',
  '펀드','ETF','연기금','국민연금','순매수','순매도'];

const WEAK = ['투자','자금','자본','시장','경기','경제','산업','수출','수입','성장률',
  '기업','대기업','중소기업','스타트업','상장사','계약','수주',
  '정부','정책','대출','예금','은행','보험','증권사','카드사',
  '반도체','배터리','바이오','조선','철강','자동차','유통','건설'];

// --- 1) 시트 이력을 Set으로 (최근 7일치만) ---
const cutoff = new Date(Date.now() - HISTORY_DAYS * 86400 * 1000);
const historySet = new Set();
let historyRowsRead = 0;

let historyItems = [];
try { historyItems = $('이력 조회').all(); } catch (e) { historyItems = []; }

for (const h of historyItems) {
  const hj = h.json || {};
  const hash = String(hj.url_hash || '').trim();
  if (!hash) continue;
  historyRowsRead++;
  const rd = hj.run_date ? new Date(String(hj.run_date) + 'T00:00:00+09:00') : null;
  if (rd && !isNaN(rd.getTime()) && rd < cutoff) continue;
  historySet.add(hash);
}

// --- 2) 필터링 ---
const inputs = $input.all().filter(i => !i.json._empty);
const counters = (inputs[0] && inputs[0].json._counters) || ($input.first().json._counters) || {};
const stats = {
  raw: counters.raw || 0,
  out_of_window: counters.out_of_window || 0,
  dup_in_run: counters.dup_in_run || 0,
  collected: inputs.length,
  history_rows: historyRowsRead,
  history_active: historySet.size,
  dup_blocked: 0,
  keyword_blocked: 0,
  passed: 0,
};

const out = [];

for (const item of inputs) {
  const j = item.json;

  // (a) 중복 대조 - REQ-03, LLM 이전
  if (historySet.has(j.url_hash)) { stats.dup_blocked++; continue; }

  // (b) 금융 키워드 필터 - REQ-04, LLM 이전
  const title = String(j.title || '');
  const body  = title + ' ' + String(j.snippet || '');

  if (BLOCK.some(k => body.includes(k))) { stats.keyword_blocked++; continue; }

  const strongHits = STRONG.filter(k => body.includes(k));
  const weakHits   = WEAK.filter(k => body.includes(k));

  // v1.2: STRONG 키워드 1개 이상 필수.
  // 피드 3개가 모두 경제면이라 WEAK(시장/경제/기업...)만으로는 사실상 전수 통과했음.
  if (strongHits.length === 0) { stats.keyword_blocked++; continue; }

  let score = strongHits.length * 2 + weakHits.length;
  if (strongHits.some(k => title.includes(k))) score += 1;

  if (score < SCORE_MIN) { stats.keyword_blocked++; continue; }

  stats.passed++;
  out.push({ json: Object.assign({}, j, {
    filter_score: score,
    matched_keywords: strongHits.concat(weakHits).slice(0, 8).join(','),
    _stats: stats,
  })});
}

if (out.length === 0) {
  const f = $input.first().json;
  return [{ json: { _empty: true, run_id: f.run_id || '', run_date: f.run_date || '', _stats: stats } }];
}
return out;

// 5b 일일 LLM 상한 + 배치 묶기  (v1.2 신규)
// Mode: Run Once for All Items
//
// Gemini 무료 티어는 분당 5요청 / 일일 250요청 제한.
// 건별 호출이면 하루 수백 건에서 429가 납니다.
//  (1) filter_score 상위 LLM_MAX건만 LLM으로 보내고
//  (2) BATCH_SIZE건씩 한 프롬프트로 묶어 호출 수를 1/10로 줄입니다.
//
// 상한에 걸려 제외된 기사는 '시트에 기록하지 않습니다'.
// 기록하면 중복 키가 생겨 내일 다시 평가받을 기회가 영영 사라지기 때문입니다.

const LLM_MAX      = 40;   // 하루 LLM 대상 상한 (배치 4회 = 무료 티어 분당 5회 이내)
const BATCH_SIZE   = 10;   // 한 번의 LLM 호출에 넣을 기사 수
const SNIPPET_MAX  = 600;  // 배치 프롬프트용 본문 발췌 상한

const inputs = $input.all().filter(i => !i.json._empty);
const head = $input.first().json;
const stats = Object.assign({}, head._stats || {});

function emptyOut() {
  return [{ json: {
    _empty: true,
    run_id: head.run_id || '',
    run_date: head.run_date || '',
    _stats: Object.assign(stats, { llm_selected: 0, llm_skipped: 0, llm_calls: 0 }),
  }}];
}

if (inputs.length === 0) { return emptyOut(); }

// --- 우선순위 정렬: 필터 점수 높은 순 -> 최신 순 ---
const ranked = inputs.map(i => i.json).sort((a, b) => {
  if ((b.filter_score || 0) !== (a.filter_score || 0)) {
    return (b.filter_score || 0) - (a.filter_score || 0);
  }
  return String(b.published_at).localeCompare(String(a.published_at));
});

const selected = ranked.slice(0, LLM_MAX);
stats.llm_selected = selected.length;
stats.llm_skipped  = ranked.length - selected.length;

if (selected.length === 0) { return emptyOut(); }

// --- 배치로 자르기 ---
const out = [];
for (let s = 0; s < selected.length; s += BATCH_SIZE) {
  const chunk = selected.slice(s, s + BATCH_SIZE);
  const batchNo = Math.floor(s / BATCH_SIZE) + 1;

  // 기사에 배치 내 지역 id 부여 (LLM 응답을 되짚을 키)
  const articles = chunk.map((a, k) => Object.assign({}, a, { id: k + 1 }));

  const promptBlock = articles.map(a =>
    '### id: ' + a.id + '\n' +
    '[매체] ' + a.source + '\n' +
    '[제목] ' + a.title + '\n' +
    '[발행] ' + a.published_at + '\n' +
    '[본문발췌] ' + String(a.snippet || '').slice(0, SNIPPET_MAX)
  ).join('\n\n');

  out.push({ json: {
    batch_no: batchNo,
    count: articles.length,
    ids: articles.map(a => a.id),
    articles,
    prompt_block: '아래 ' + articles.length + '건의 기사를 각각 분석하십시오.\n' +
                  '반드시 ' + articles.length + '개의 결과를 모두 반환하고, 각 결과의 id는 입력 id와 정확히 일치시키십시오.\n\n' +
                  promptBlock,
    run_id: head.run_id || '',
    run_date: head.run_date || '',
    _stats: stats,
  }});
}

stats.llm_calls = out.length;
return out;

// 9 배치 해체 + 검증 안전판 (V-1 ~ V-7)
// Mode: Run Once for All Items
//
// 입력: LLM 노드 출력 (배치 1개당 아이템 1개, output.results 배열)
// 출력: 기사 1건당 아이템 1개

const CATEGORIES = new Set(['증시','금리','환율','부동산','기업','정책','기타']);
const SRC = '상한+배치';

function sentenceTrim(text, max) {
  const parts = String(text).split(/(?<=[.!?。])\s+/).filter(s => s.trim());
  return { text: parts.slice(0, max).join(' ').trim(), over: parts.length > max };
}

const items = $input.all();
const srcAll = $(SRC).all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const j = items[i].json || {};

  // 배치 원본 복원 (LLM 노드는 output만 남기므로 인덱스로 페어링)
  let batch = {};
  try { batch = $(SRC).itemMatching(i).json; }
  catch (e) { batch = (srcAll[i] && srcAll[i].json) || {}; }

  const articles = Array.isArray(batch.articles) ? batch.articles : [];

  const llm = (j.output && typeof j.output === 'object') ? j.output
            : (j.data && typeof j.data === 'object') ? j.data
            : null;
  const results = (llm && Array.isArray(llm.results)) ? llm.results : [];

  const byId = new Map();
  for (const r of results) {
    const rid = Number(r && r.id);
    if (Number.isInteger(rid) && !byId.has(rid)) byId.set(rid, r);
  }

  for (const a of articles) {
    const meta = {
      url_hash: a.url_hash, normalized_url: a.normalized_url,
      original_url: a.original_url, title: a.title, source: a.source,
      published_at: a.published_at, run_id: a.run_id || batch.run_id,
      run_date: a.run_date || batch.run_date,
      filter_score: a.filter_score, matched_keywords: a.matched_keywords,
      _stats: batch._stats,
    };

    // V-1: 배치 호출 자체가 실패
    if (j.error || !llm) {
      out.push({ json: Object.assign({}, meta, {
        summary: '', importance: 1, category: '기타',
        needs_review: true, review_flags: 'V1_llm_error',
      })});
      continue;
    }

    const r = byId.get(Number(a.id));

    // V-7: 배치는 성공했으나 이 기사의 결과가 누락됨
    if (!r) {
      out.push({ json: Object.assign({}, meta, {
        summary: '', importance: 1, category: '기타',
        needs_review: true, review_flags: 'V7_missing_in_batch',
      })});
      continue;
    }

    let needsReview = false;
    const flags = [];
    let importance = 1;
    let category = '기타';

    let summary = String(r.summary == null ? '' : r.summary).trim();

    // V-6: 코드펜스 / URL 잔여물
    const cleaned = summary.replace(/```[a-z]*\n?/gi, '').replace(/https?:\/\/\S+/g, '').trim();
    if (cleaned !== summary) { needsReview = true; flags.push('V6_artifact'); }
    summary = cleaned;

    // V-2
    if (summary.length < 10) { needsReview = true; flags.push('V2_too_short'); }

    // V-3
    const st = sentenceTrim(summary, 3);
    if (st.over) { needsReview = true; flags.push('V3_too_many_sentences'); }
    summary = st.text;

    // V-4
    const impNum = Number(r.importance);
    if (!Number.isInteger(impNum) || impNum < 1 || impNum > 5) {
      importance = 1; needsReview = true; flags.push('V4_bad_importance');
    } else {
      importance = impNum;
    }

    // V-5
    const cat = String(r.category == null ? '' : r.category).trim();
    if (!CATEGORIES.has(cat)) {
      category = '기타'; needsReview = true; flags.push('V5_bad_category');
    } else {
      category = cat;
    }

    out.push({ json: Object.assign({}, meta, {
      summary, importance, category,
      needs_review: needsReview,
      review_flags: flags.join('|'),
    })});
  }
}

return out;

// 9b 발송 선별 + 메시지 조립 (v1.4 신규)
// Mode: Run Once for All Items
//
// [이 노드가 생긴 이유]
// v1.3까지는 '이력 기록'이 '브리핑 조립'보다 먼저 실행됐습니다.
// 그래서 시트는 길이 제한(2000자)에 몇 건이 잘렸는지 알 수 없었고,
// 중요도만 보고 sent=TRUE를 찍었습니다.
// 결과: 실제로 발송되지 않은 중요 기사가 시트에 남아 다음날 중복 차단 -> 영구 유실.
//
// 이 노드가 '실제로 메시지에 들어갈 기사'를 먼저 확정한 뒤,
//   - 발송된 기사        -> sent=true 로 기록
//   - 중요도 1~3 / 검증실패 -> sent=false 로 기록 (D-02 유지: 재요약 방지)
//   - 중요도 4+ 인데 잘린 기사 -> 아예 출력하지 않음 (시트 미기록) -> 내일 재도전

const MIN_IMPORTANCE = 4;
const MAX_ARTICLES   = 15;    // 길이 가드가 실질 상한을 정하므로 넉넉히
const SUMMARY_MAX    = 90;    // v1.4: 요약 압축 (첫 문장만, 90자)
const HARD_LIMIT     = 1950;  // Discord 본문 2000자 대비 여유

const CAT_ORDER = ['금리','정책','증시','환율','기업','부동산','기타'];

const items = $input.all().map(i => i.json).filter(j => j && j.url_hash);

let stats = {};
let runDate = '';
try {
  const f = $('상한+배치').first().json;
  stats = f._stats || {};
  runDate = f.run_date || '';
} catch (e) { stats = {}; }
if (!runDate) {
  runDate = (items[0] && items[0].run_date) ||
            new Intl.DateTimeFormat('sv-SE', { timeZone: 'Asia/Seoul' }).format(new Date());
}

function countLine(n) {
  let s = '수집 ' + (stats.raw || 0) + '건 → 시간창 ' + (stats.collected || 0) + '건 → ' +
          '중복제외 ' + ((stats.collected || 0) - (stats.dup_blocked || 0)) + '건 → ' +
          '금융필터 ' + (stats.passed || 0) + '건';
  if (stats.llm_skipped > 0) {
    s += ' → LLM대상 ' + (stats.llm_selected || 0) + '건(상한제외 ' + stats.llm_skipped + ')';
  }
  return s + ' → 중요도4+ ' + n + '건';
}

function firstSentence(t) {
  const parts = String(t).split(/(?<=[.!?。])\s+/).filter(s => s.trim());
  return parts.length ? parts[0].trim() : String(t).trim();
}

// --- 발송 후보 ---
const candidates = items.filter(j =>
  j.needs_review !== true && Number(j.importance) >= MIN_IMPORTANCE);

candidates.sort((a, b) => {
  if (b.importance !== a.importance) return b.importance - a.importance;
  const ca = CAT_ORDER.indexOf(a.category), cb = CAT_ORDER.indexOf(b.category);
  if (ca !== cb) return ca - cb;
  return String(b.published_at).localeCompare(String(a.published_at));
});

function build(list) {
  if (list.length === 0) {
    return [
      '📭 오늘의 금융 브리핑 (' + runDate + ')',
      '중요도 4 이상 기사가 없습니다.',
      '',
      countLine(0),
    ].join('\n');
  }
  const body = list.map((a, idx) => {
    let sum = firstSentence(String(a.summary || '').trim());
    if (sum.length > SUMMARY_MAX) sum = sum.slice(0, SUMMARY_MAX - 1) + '…';
    return '[' + (idx + 1) + '] ⭐' + a.importance + ' ' + a.category + ' | ' + a.title + '\n' +
           '  ' + sum + '\n' +
           '  📰 ' + a.source + ' 🔗 <' + a.original_url + '>';
  }).join('\n');

  const lines = [
    '📈 오늘의 금융 브리핑 (' + runDate + ')',
    '읽을 기사 ' + candidates.length + '건',
    '',
    body,
  ];
  const hidden = candidates.length - list.length;
  if (hidden > 0) lines.push('', '… 외 ' + hidden + '건은 길이 제한으로 생략');
  // 정상 브리핑에는 파이프라인 카운트 줄을 넣지 않는다(자리만 차지).
  // 0건 메시지에서만 유지 -> REQ-06 '조용한 날 vs 고장' 구분 장치.
  return lines.join('\n');
}

// --- 길이 가드: 실제로 들어갈 기사 확정 ---
let shown = candidates.slice(0, MAX_ARTICLES);
let content = build(shown);
while (content.length > HARD_LIMIT && shown.length > 1) {
  shown = shown.slice(0, shown.length - 1);
  content = build(shown);
}
if (content.length > HARD_LIMIT) content = content.slice(0, HARD_LIMIT - 1) + '…';

const shownSet = new Set(shown.map(a => a.url_hash));
const droppedCount = candidates.length - shown.length;

// --- 시트 기록 (LLM을 탄 기사 전부, D-02 유지) ---
// v1.5: 잘린 기사도 기록한다.
//   시간 창이 24h이므로 그 기사는 내일 창 밖으로 나가 어차피 다시 오지 않는다.
//   기록해 두어야 같은 날 재실행 시 중복 요약을 막을 수 있다.
//   sent 값만 실제 발송 여부와 정확히 일치시킨다.
const out = items.map(j => ({ json: Object.assign({}, j, {
  sent: shownSet.has(j.url_hash),
  briefing_content: content,
  dropped_count: droppedCount,
})}));

// 기록할 것이 없는 경우에도 브리핑은 나가야 하므로 신호 아이템 유지
if (out.length === 0) {
  return [{ json: {
    _norecord: true,
    run_date: runDate,
    sent: false,
    briefing_content: content,
    dropped_count: droppedCount,
  }}];
}
return out;

// 11 브리핑 발송 준비 (REQ-06)
// Mode: Run Once for All Items
//
// v1.4부터 메시지 본문은 '발송선별' 노드가 만듭니다(실제 발송분 확정과 같은 곳에서 계산해야
// sent 값과 메시지 내용이 어긋나지 않기 때문). 이 노드는 그 결과를 집어 1건으로 내보내고,
// LLM을 아예 타지 않은 날(0건 경로)의 메시지만 여기서 직접 만듭니다.

let content = '';
try {
  const f = $('발송선별').first().json;
  if (f && f.briefing_content) content = f.briefing_content;
} catch (e) { content = ''; }

if (!content) {
  // --- 0건 경로: 중복/필터에서 전멸해 LLM을 타지 않은 날 ---
  let stats = {};
  let runDate = '';
  try {
    const g = $('상한+배치').first().json;
    stats = g._stats || {};
    runDate = g.run_date || '';
  } catch (e) { stats = {}; }
  if (!stats || Object.keys(stats).length === 0) {
    try {
      const h = $('중복대조+키워드필터').first().json;
      stats = h._stats || {};
      runDate = runDate || h.run_date || '';
    } catch (e) { stats = stats || {}; }
  }
  if (!runDate) {
    runDate = new Intl.DateTimeFormat('sv-SE', { timeZone: 'Asia/Seoul' }).format(new Date());
  }

  let line = '수집 ' + (stats.raw || 0) + '건 → 시간창 ' + (stats.collected || 0) + '건 → ' +
             '중복제외 ' + ((stats.collected || 0) - (stats.dup_blocked || 0)) + '건 → ' +
             '금융필터 ' + (stats.passed || 0) + '건';
  if (stats.llm_skipped > 0) {
    line += ' → LLM대상 ' + (stats.llm_selected || 0) + '건(상한제외 ' + stats.llm_skipped + ')';
  }
  line += ' → 중요도4+ 0건';

  content = [
    '📭 오늘의 금융 브리핑 (' + runDate + ')',
    '중요도 4 이상 기사가 없습니다.',
    '',
    line,
  ].join('\n');
}

return [{ json: { content } }];
